-- =============================================
-- DATOS: Sincronización de la flota de vehículos con el listado oficial
-- Fuente: export EP006112026_070257.xlsx (06/11/2026), 100 vehículos
--         Zona de gestión CADIZ, puntos BARBATE y BARBATE (URG).
--
-- Qué hace:
--   1. Elimina 4 duplicados sin historial: 3782JXN, 6852LMW, 7331GXD, 9021KGN.
--   2. Corrige 87 vehículos existentes (matrícula/bastidor mal escritos) sobre
--      el mismo registro, conservando su historial. Actualiza estado,
--      clasificación (A1, A1 UR, A2, B, C), tipo_vehiculo, zona_cobertura
--      (punto de gestión), color, combustible, fecha de matriculación y año.
--   3. Crea 13 vehículos nuevos con ITV/seguro/homologación provisionales.
--
-- Mapeos:
--   Estado:  OPERATIVO -> activo | BAJA -> baja | AVERIADO -> reparacion
--   Tipo:    A1, A1 UR -> CONVENCIONAL | A2 -> COLECTIVA | B, C -> UVI MÓVIL
--
-- IDEMPOTENTE: solo se ejecuta si existe la matrícula antigua '0084GMG'.
-- Ya aplicada en producción (ycmopmnrhrpnnzkvnihr) el 06/11/2026.
-- =============================================

DO $mig$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.tvehiculos WHERE matricula = '0084GMG') THEN
    RAISE NOTICE 'Flota ya sincronizada: no se aplica nada';
    RETURN;
  END IF;

delete from public.tvehiculos where matricula in ('3782JXN','6852LMW','7331GXD','9021KGN');
  -- Liberar bastidores temporalmente para evitar choques del UNIQUE durante el update
update public.tvehiculos set numero_bastidor='TMP-'||numero_bastidor;
