update public.tvehiculos v set
  matricula=x.mat,
  numero_bastidor=coalesce(x.bast, substr(v.numero_bastidor,5)),
  estado=x.estado, operativo=x.operativo, disponible=x.operativo,
  fecha_baja=x.fbaja::timestamptz, motivo_baja=case when x.estado='baja' then coalesce(v.motivo_baja,'BAJA (importación listado oficial)') end,
  clasificacion=x.clasif, tipo_vehiculo=x.tipo, categoria='AMBULANCIA', zona_cobertura=x.zona,
  marca=coalesce(x.marca,v.marca), modelo=coalesce(x.modelo,v.modelo),
  color=coalesce(x.color,v.color), tipo_combustible=coalesce(x.comb,v.tipo_combustible),
  fecha_primera_matriculacion=coalesce(x.fmat::date,v.fecha_primera_matriculacion),
  anio_fabricacion=coalesce(x.anio,v.anio_fabricacion), activo=true
from x where x.src is not null and v.matricula=x.src;
