insert into public.tvehiculos (matricula,numero_bastidor,estado,operativo,disponible,fecha_baja,motivo_baja,clasificacion,tipo_vehiculo,categoria,zona_cobertura,
  marca,modelo,color,tipo_combustible,fecha_primera_matriculacion,anio_fabricacion,km_actual,proxima_itv,fecha_vencimiento_seguro,
  homologacion_sanitaria,fecha_vencimiento_homologacion,empresa_id,activo)
select x.mat, coalesce(x.bast,'SIN-BASTIDOR-'||x.mat), x.estado, x.operativo, x.operativo, x.fbaja::timestamptz,
  case when x.estado='baja' then 'BAJA (importación listado oficial)' end, x.clasif, x.tipo, 'AMBULANCIA', x.zona,
  coalesce(x.marca,'PENDIENTE'), coalesce(x.modelo,'PENDIENTE'), x.color, x.comb, x.fmat::date, coalesce(x.anio,2025), 0,
  '2026-12-16','2026-12-16','PENDIENTE','2027-12-16','00000000-0000-0000-0000-000000000001', true
from x where x.src is null;

  IF (SELECT count(*) FROM public.tvehiculos) <> 100 THEN
    RAISE EXCEPTION 'Total de vehículos distinto de 100: %', (SELECT count(*) FROM public.tvehiculos);
  END IF;
  IF EXISTS (SELECT 1 FROM public.tvehiculos WHERE numero_bastidor LIKE 'TMP-%') THEN
    RAISE EXCEPTION 'Quedan bastidores temporales TMP-';
  END IF;
END
$mig$;
